    "assert _eq_outer(candidate([['m', 'a', 'r', 't'], ['a', 't', 'e', 'n'], ['r', 'e', 't', 'a'], ['t', 'a', 'n', 'e']], ['mart', 'rate', 'tane', 'tart', 'ten', 'mate', 'ment', 'taen', 'meta', 'atma']), ['mart', 'mate', 'rate', 'tart', 'ten', 'tane', 'taen'])",
    "assert _eq_outer(candidate([['a', 'b', 'c'], ['a', 'e', 'd'], ['e', 'f', 'g']], ['abc', 'bce', 'fed', 'def']), ['abc', 'def', 'fed'])",
    "assert _eq_outer(candidate([['o', 'a', 'a', 'n'], ['e', 't', 'a', 'e'], ['i', 'h', 'k', 'r'], ['i', 'f', 'l', 'v'], ['g', 'h', 'i', 'j']], ['oath', 'pea', 'eat', 'rain', 'ghij', 'gfedcba', 'nihao']), ['oath', 'eat', 'ghij'])",
